en waraxe","exotic","one_handed","melee",20,3,null,null,0,"and","1d8","1d10",null,null,["slashing"],3000,8,"Dwarven weapon familiarity may treat this as martial."],["whip","Whip","exotic","one_handed","melee",20,2,null,15,1,"and","1d2","1d3",null,null,["slashing"],100,2,"Reach weapon with special threat and armor interaction; normally deals nonlethal damage."],["orc-double-axe","Orc double axe","exotic","two_handed","melee",20,3,null,null,0,"and","1d6","1d8","1d6","1d8",["slashing"],6000,15,"Double weapon."],["spiked-chain","Spiked chain","exotic","two_handed","melee",20,2,null,10,1,"and","1d6","2d4",null,null,["piercing"],2500,10,"Reach weapon that can also attack adjacent foes; can be used for trip/disarm."],["dire-flail","Dire flail","exotic","two_handed","melee",20,2,null,null,0,"and","1d6","1d8","1d6","1d8",["bludgeoning"],9000,10,"Double weapon; special trip/disarm interaction."],["gnome-hooked-hammer","Gnome hooked hammer","exotic","two_handed","melee",20,3,null,null,0,"or","1d6","1d8","1d4","1d6",["bludgeoning","piercing"],2000,6,"Double weapon. Hammer head critical x3; pick head critical x4. Gnome familiarity may treat it as martial."],["two-bladed-sword","Two-bladed sword","exotic","two_handed","melee",19,2,null,null,0,"and","1d6","1d8","1d6","1d8",["slashing"],10000,10,"Double weapon."],["dwarven-urgrosh","Dwarven urgrosh","exotic","two_handed","melee",20,3,null,null,0,"or","1d6","1d8","1d4","1d6",["slashing","piercing"],5000,12,"Double weapon with axe and spear ends. Dwarven familiarity may treat it as martial."],["bolas","Bolas","exotic","ranged","ranged",20,2,10,null,0,"and","1d3","1d4",null,null,["bludgeoning"],500,2,"Deals nonlethal damage and can trip at range."],["hand-crossbow","Hand crossbow","exotic","ranged","ranged",19,2,30,null,0,"and","1d3","1d4",null,null,["piercing"],10000,2,"Uses crossbow bolts."],["repeating-heavy-crossbow","Repeating heavy crossbow","exotic","ranged","ranged",19,2,120,null,0,"and","1d8","1d10",null,null,["piercing"],40000,12,"Uses a repeating crossbow case; special reload rules apply."],["repeating-light-crossbow","Repeating light crossbow","exotic","ranged","ranged",19,2,80,null,0,"and","1d6","1d8",null,null,["piercing"],25000,6,"Uses a repeating crossbow case; special reload rules apply."],["net","Net","exotic","ranged","ranged",20,2,10,null,0,"and",null,null,null,null,[],2000,6,"Entangles rather than dealing weapon damage; special net rules apply."],["shuriken-5","Shuriken (5)","exotic","ranged","ranged",20,2,10,null,0,"and","1","1d2",null,null,["piercing"],100,0.5,"Package of five. Shuriken are treated as ammunition for drawing, crafting, and recovery rules."]]');

INSERT INTO dnd35_items
(id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,price_copper,weight_pounds,size,hardness,hit_points)
SELECT 'phb-item-'||slug,'phb-3.5','112-121',slug,name,'Player''s Handbook weapon.',special_text,0,NULL,1,'weapon',price_copper,weight_lb,NULL,NULL,NULL
FROM _phb_weapon_seed d
WHERE NOT EXISTS (SELECT 1 FROM dnd35_items i WHERE i.source_id='phb-3.5' AND i.slug=d.slug AND i.owner_user_id IS NULL);

INSERT OR IGNORE INTO dnd35_weapons
(item_id,proficiency,handedness,attack_kind,critical_threat_minimum,critical_multiplier,range_increment_feet,reach_feet,is_reach,damage_type_mode,special_text)
SELECT 'phb-item-'||slug,proficiency,handedness,attack_kind,crit_min,crit_mult,range_ft,reach_ft,is_reach,damage_mode,special_text
FROM _phb_weapon_seed;

INSERT OR IGNORE INTO dnd35_weapon_damage(weapon_id,size,weapon_end,dice)
SELECT 'phb-item-'||slug,'small',1,dmg_small FROM _phb_weapon_seed
UNION ALL SELECT 'phb-item-'||slug,'medium',1,dmg_medium FROM _phb_weapon_seed
UNION ALL SELECT 'phb-item-'||slug,'small',2,end2_small FROM _phb_weapon_seed WHERE end2_small IS NOT NULL
UNION ALL SELECT 'phb-item-'||slug,'medium',2,end2_medium FROM _phb_weapon_seed WHERE end2_medium IS NOT NULL;

INSERT OR IGNORE INTO dnd35_weapon_damage_types(weapon_id,damage_type)
SELECT 'phb-item-'||w.slug,t.value
FROM _phb_weapon_seed w, json_each(w.damage_types) t;

CREATE TEMP TABLE _phb_ammo_seed AS
SELECT json_extract(value,'$[0]') slug,json_extract(value,'$[1]') name,json_extract(value,'$[2]') kind,
       json_extract(value,'$[3]') qty,json_extract(value,'$[4]') price_copper,json_extract(value,'$[5]') weight_lb,
       json_extract(value,'$[6]') weapon_slugs
FROM json_each('[["crossbow-bolts-10","Crossbow bolts (10)","crossbow_bolt",10,100,1.0,["heavy-crossbow","light-crossbow","hand-crossbow"]],["sling-bullets-10","Sling bullets (10)","sling_bullet",10,10,5.0,["sling"]],["arrows-20","Arrows (20)","arrow",20,100,3.0,["longbow","shortbow","composite-longbow","composite-shortbow"]]]');

INSERT INTO dnd35_items
(id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,price_copper,weight_pounds,size,hardness,hit_points)
SELECT 'phb-item-'||slug,'phb-3.5','116-121',slug,name,'Player''s Handbook ammunition.','Use with compatible ranged weapons.',0,NULL,1,'ammunition',price_copper,weight_lb,NULL,NULL,NULL
FROM _phb_ammo_seed d
WHERE NOT EXISTS (SELECT 1 FROM dnd35_items i WHERE i.source_id='phb-3.5' AND i.slug=d.slug AND i.owner_user_id IS NULL);

INSERT OR IGNORE INTO dnd35_ammunition(item_id,kind,quantity_per_package,special_text)
SELECT 'phb-item-'||slug,kind,qty,'Standard PHB ammunition package.' FROM _phb_ammo_seed;

INSERT OR IGNORE INTO dnd35_ammunition_weapons(ammunition_id,weapon_id)
SELECT 'phb-item-'||a.slug,'phb-item-'||w.value
FROM _phb_ammo_seed a, json_each(a.weapon_slugs) w;

DROP TABLE _phb_ammo_seed;
DROP TABLE _phb_weapon_seed;
